package net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html;

import java.net.URI;
import java.util.HashSet;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Stream;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.core.UriBuilder;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.session.domain.SessionInfo;
import net.civeira.phylax.feature.oauth.session.domain.gateway.SessionStoreGateway;

/**
 * Link from the profile pages back to the application that opened them.
 *
 * <p>
 * The return URL comes from the {@code back} parameter or the {@code Referer}, both chosen by the
 * browser, so it is accepted only when its origin is the origin of a redirect (login or
 * post-logout) registered by a client that took part in the browser session. Any other URL is
 * ignored and the page shows no link back.
 *
 * <p>
 * The link carries {@code iss} with the issuer of the tenant (OpenID Connect third-party initiated
 * login): an application that sees its own issuer retries a silent login ({@code prompt=none}) and
 * picks up the session. {@code iss} is not a credential: the SPA only accepts an answer to a
 * request it started itself (state and PKCE).
 */
@RequestScoped
@RequiredArgsConstructor
public class ProfileBackLink {
  private static final String ISS = "iss";

  private final SessionStoreGateway sessions;
  private final ClientStoreGateway clients;
  private final CurrentRequest current;

  /**
   * The return URL when it belongs to an application of the session.
   *
   * @param tenant tenant of the profile
   * @param cookie browser session identifier
   * @param session browser session
   * @param url candidate return URL
   * @return the URL, empty when its origin is not registered by a client of the session
   */
  public Optional<String> accept(String tenant, String cookie, SessionInfo session, String url) {
    Optional<URI> target = parse(url);
    if (target.isEmpty() || target.get().getRawUserInfo() != null) {
      return Optional.empty();
    }
    Set<String> participants = new HashSet<>(sessions.participatingClients(cookie));
    if (session.getClientId() != null && !session.getClientId().isBlank()) {
      participants.add(session.getClientId());
    }
    String origin = origin(target.get());
    boolean registered = participants.stream()
        .map(clientId -> clients.loadPreautorized(tenant, clientId)).flatMap(Optional::stream)
        .flatMap(ProfileBackLink::registeredUris).map(ProfileBackLink::parse)
        .flatMap(Optional::stream).map(ProfileBackLink::origin).anyMatch(origin::equals);
    return registered ? Optional.of(url) : Optional.empty();
  }

  /**
   * The return URL with the issuer of the tenant in {@code iss}, keeping its query and fragment.
   *
   * @param tenant tenant of the profile
   * @param url accepted return URL
   * @return the URL to link to
   */
  public String withIssuer(String tenant, String url) {
    try {
      return UriBuilder.fromUri(URI.create(url)).replaceQueryParam(ISS, issuer(tenant)).build()
          .toString();
    } catch (RuntimeException ex) {
      return url;
    }
  }

  private String issuer(String tenant) {
    return current.getPublicHost() + "/oauth/openid/" + tenant;
  }

  private static Stream<String> registeredUris(ClientDetails client) {
    return Stream.concat(client.getAllowedRedirectUris().stream(),
        client.getPostLogoutRedirectUris().stream());
  }

  private static Optional<URI> parse(String url) {
    if (url == null || url.isBlank()) {
      return Optional.empty();
    }
    try {
      URI uri = URI.create(url);
      String scheme = uri.getScheme();
      if (uri.getHost() == null || scheme == null
          || !"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme)) {
        return Optional.empty();
      }
      return Optional.of(uri);
    } catch (IllegalArgumentException ex) {
      return Optional.empty();
    }
  }

  private static String origin(URI uri) {
    String scheme = uri.getScheme().toLowerCase(Locale.ROOT);
    int port = uri.getPort() != -1 ? uri.getPort() : "https".equals(scheme) ? 443 : 80;
    return scheme + "://" + uri.getHost().toLowerCase(Locale.ROOT) + ":" + port;
  }
}
